import { KEATING_WEB_ORIGIN } from "../product-links";
import { parseSetCookie } from "./cookie-jar";
import {
  COURSE_ACCOUNT_COOKIE_NAME,
  courseAccountCredentialKey,
  getCourseCredentialStore,
} from "./credentials";
import {
  type CourseListItem,
  type CourseSessionAccount,
  type CourseViewerSnapshot,
  normalizeCourseListItem,
  normalizeCourseSnapshot,
} from "./types";

const DEFAULT_REQUEST_TIMEOUT_MS = 15_000;
const COOKIE_VALUE_PATTERN = /^[A-Za-z0-9._~-]{1,512}$/;

/** A course request that failed with the server's own error code attached. */
export class CourseApiError extends Error {
  constructor(readonly status: number, message: string, readonly code: string) {
    super(message);
    this.name = "CourseApiError";
  }

  /** True when the learner is not a member, or the invite did not apply. */
  get isAccessProblem(): boolean {
    return this.status === 401 || this.status === 403 || this.status === 404;
  }
}

let courseCredential: string | null | undefined;

function isCourseAccountCredential(value: unknown): value is string {
  return typeof value === "string" && COOKIE_VALUE_PATTERN.test(value);
}

async function loadCourseCredential(): Promise<string | null> {
  if (courseCredential !== undefined) return courseCredential;
  try {
    const raw = await getCourseCredentialStore().getItem(courseAccountCredentialKey());
    courseCredential = isCourseAccountCredential(raw) ? raw : null;
  } catch {
    courseCredential = null;
  }
  return courseCredential;
}

async function rememberCookies(header: string | null): Promise<void> {
  const credential = parseSetCookie(header)[COURSE_ACCOUNT_COOKIE_NAME];
  if (credential === undefined) return;
  if (!isCourseAccountCredential(credential)) {
    courseCredential = null;
    await getCourseCredentialStore().deleteItem(courseAccountCredentialKey()).catch(() => undefined);
    return;
  }
  courseCredential = credential;
  await getCourseCredentialStore().setItem(courseAccountCredentialKey(), credential).catch(() => undefined);
}

/** Drops the stored session; the next request starts a fresh course account. */
export async function clearCourseSession(): Promise<void> {
  courseCredential = null;
  await getCourseCredentialStore().deleteItem(courseAccountCredentialKey()).catch(() => undefined);
}

export interface CourseRequestOptions {
  signal?: AbortSignal;
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
}

async function request<T>(
  path: string,
  init: RequestInit,
  normalize: (payload: unknown) => T,
  options: CourseRequestOptions = {},
): Promise<T> {
  const { signal: upstreamSignal, fetchImpl = fetch, timeoutMs = DEFAULT_REQUEST_TIMEOUT_MS } = options;
  const credential = await loadCourseCredential();
  const controller = new AbortController();
  let timedOut = false;
  const abortForUpstream = () => controller.abort();
  if (upstreamSignal?.aborted) controller.abort();
  else upstreamSignal?.addEventListener("abort", abortForUpstream, { once: true });
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, Math.max(1, timeoutMs));
  const headers: Record<string, string> = {
    Accept: "application/json",
    ...(init.body ? { "Content-Type": "application/json" } : {}),
    ...(credential ? { Cookie: `${COURSE_ACCOUNT_COOKIE_NAME}=${credential}` } : {}),
  };

  try {
    const response = await fetchImpl(`${KEATING_WEB_ORIGIN}/api/courses${path}`, {
      ...init,
      headers,
      signal: controller.signal,
    });
    await rememberCookies(response.headers.get("set-cookie"));

    const text = await response.text();
    let payload: unknown = null;
    try {
      payload = text ? JSON.parse(text) : null;
    } catch {
      payload = null;
    }

    if (!response.ok) {
      const body = (payload ?? {}) as Record<string, unknown>;
      const data = (body.data ?? {}) as Record<string, unknown>;
      const message = typeof body.statusMessage === "string" && body.statusMessage
        ? body.statusMessage
        : typeof body.message === "string" && body.message
          ? body.message
          : `The course server returned HTTP ${response.status}.`;
      throw new CourseApiError(
        response.status,
        message,
        typeof data.code === "string" ? data.code : "course_request_failed",
      );
    }

    return normalize(payload);
  } catch (error) {
    if (error instanceof CourseApiError) throw error;
    if (timedOut) {
      throw new CourseApiError(0, "The course server took too long to respond. Please try again.", "course_timeout");
    }
    if (error instanceof Error && error.name === "AbortError") throw error;
    throw new CourseApiError(0, "Could not reach Keating. Check your connection.", "course_offline");
  } finally {
    clearTimeout(timer);
    upstreamSignal?.removeEventListener("abort", abortForUpstream);
  }
}

export function fetchCourseSession(options?: CourseRequestOptions): Promise<CourseSessionAccount> {
  return request("/session", { method: "GET" }, (payload) => {
    const root = asRecord(payload);
    const account = asRecord(root.account);
    const mode = account.mode;
    if (!isNonEmptyString(account.id) || !isNonEmptyString(account.displayName)
      || (mode !== "local" && mode !== "hosted" && mode !== "development")) {
      throw invalidSuccess("The course server returned an incomplete session.");
    }
    return {
      id: account.id,
      displayName: account.displayName,
      mode,
    };
  }, options);
}

export function fetchCourses(options?: CourseRequestOptions): Promise<CourseListItem[]> {
  return request("", { method: "GET" }, (payload) => {
    const courses = asRecord(payload).courses;
    if (!Array.isArray(courses) || courses.some((course) => !isNonEmptyString(asRecord(course).id))) {
      throw invalidSuccess("The course server returned an incomplete course list.");
    }
    return courses.map(normalizeCourseListItem);
  }, options);
}

/**
 * Establishes the server-owned course account before listing courses. Do not
 * parallelize these requests: a fresh local session is created by /session.
 */
export async function fetchCoursesForCurrentAccount(
  options?: CourseRequestOptions,
): Promise<{ account: CourseSessionAccount; courses: CourseListItem[] }> {
  const account = await fetchCourseSession(options);
  const courses = await fetchCourses(options);
  return { account, courses };
}

export function fetchCourse(courseId: string, options?: CourseRequestOptions): Promise<CourseViewerSnapshot> {
  return request(`/${encodeURIComponent(courseId)}`, { method: "GET" }, normalizeSnapshot, options);
}

/**
 * Redeems an invite code. `acceptTeacherAccess` is the learner's explicit
 * consent to let course teachers see their work, so it is always passed
 * through from a deliberate choice rather than defaulted on.
 */
export function joinCourse(
  inviteCode: string,
  acceptTeacherAccess: boolean,
  options?: CourseRequestOptions,
): Promise<CourseViewerSnapshot> {
  return request(
    `/join/${encodeURIComponent(inviteCode)}`,
    { method: "POST", body: JSON.stringify({ acceptTeacherAccess }) },
    normalizeSnapshot,
    options,
  );
}

/** Absolute URL for a material the app hands off to the browser. */
export function courseMaterialUrl(courseId: string, materialId: string): string {
  return `${KEATING_WEB_ORIGIN}/api/courses/${encodeURIComponent(courseId)}/materials/${encodeURIComponent(materialId)}`;
}

function asRecord(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null ? value as Record<string, unknown> : {};
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function invalidSuccess(message: string): CourseApiError {
  return new CourseApiError(200, message, "course_invalid_response");
}

function normalizeSnapshot(payload: unknown): CourseViewerSnapshot {
  const root = asRecord(payload);
  const course = asRecord(root.course);
  const viewer = asRecord(root.viewer);
  if (!isNonEmptyString(course.id) || !isNonEmptyString(viewer.accountId)) {
    throw invalidSuccess("The course server returned an incomplete course.");
  }
  return normalizeCourseSnapshot(payload);
}
import type * as SecureStoreModule from "expo-secure-store";

/**
 * The native Courses API is deliberately scoped to the one server-issued
 * account cookie. Keeping it separate from the app state prevents a course
 * identity from ending up in AsyncStorage alongside ordinary UI state.
 */
export const COURSE_ACCOUNT_COOKIE_NAME = "keating_course_account";
const COURSE_ACCOUNT_CREDENTIAL_KEY = "keating.mobile.course-account-cookie.v1";

export interface CourseCredentialStore {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
  deleteItem(key: string): Promise<void>;
}

function nativeSecureStore(): typeof SecureStoreModule {
  // Metro resolves this at runtime on a native device. Keeping it lazy lets
  // request-level tests replace the credential store without loading React
  // Native's native module into Bun.
  return require("expo-secure-store") as typeof SecureStoreModule;
}

const nativeStore: CourseCredentialStore = {
  getItem: (key) => nativeSecureStore().getItemAsync(key),
  setItem: (key, value) => {
    const secureStore = nativeSecureStore();
    return secureStore.setItemAsync(key, value, {
      keychainAccessible: secureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
    });
  },
  deleteItem: (key) => nativeSecureStore().deleteItemAsync(key),
};

let store: CourseCredentialStore = nativeStore;

export function getCourseCredentialStore(): CourseCredentialStore {
  return store;
}

/** Test seam for deterministic request-level tests; never persisted itself. */
export function setCourseCredentialStoreForTests(next: CourseCredentialStore | null): void {
  store = next ?? nativeStore;
}

export function courseAccountCredentialKey(): string {
  return COURSE_ACCOUNT_CREDENTIAL_KEY;
}
import { useRouter } from "expo-router";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  Modal,
  Pressable,
  RefreshControl,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  View,
  Linking,
} from "react-native";
import { Button } from "@/components/Buttons";
import { EmptyState } from "@/components/EmptyState";
import { Screen } from "@/components/Screen";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import {
  CourseApiError,
  clearCourseSession,
  fetchCoursesForCurrentAccount,
  joinCourse,
} from "@/lib/courses/client";
import type { CourseListItem, CourseSessionAccount } from "@/lib/courses/types";
import { PRODUCT_LINKS } from "@/lib/product-links";

export default function CoursesScreen() {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const router = useRouter();
  const [courses, setCourses] = useState<CourseListItem[] | null>(null);
  const [account, setAccount] = useState<CourseSessionAccount | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [disconnecting, setDisconnecting] = useState(false);
  const [joinOpen, setJoinOpen] = useState(false);
  const loadController = useRef<AbortController | null>(null);

  const load = useCallback(async (mode: "initial" | "refresh") => {
    loadController.current?.abort();
    const controller = new AbortController();
    loadController.current = controller;
    if (mode === "refresh") setRefreshing(true);
    setError(null);
    setErrorCode(null);
    try {
      // The server mints the local account during /session. Waiting for that
      // cookie before the list request means both requests always address the
      // same learner, even on a brand-new install.
      const { account: session, courses: list } = await fetchCoursesForCurrentAccount({ signal: controller.signal });
      if (controller.signal.aborted) return;
      setAccount(session);
      setCourses(list);
    } catch (caught) {
      if (controller.signal.aborted || (caught instanceof Error && caught.name === "AbortError")) return;
      const code = caught instanceof CourseApiError ? caught.code : null;
      setError(code === "notorganic_auth_adapter_unavailable"
        ? "Hosted course sign-in is unavailable on this server. Open Courses on the web to sign in or contact the server administrator."
        : caught instanceof Error ? caught.message : "Could not load your courses.");
      setErrorCode(code);
      // Keep whatever list is already on screen; a failed refresh should not
      // blank out courses the learner was reading.
      setCourses((current) => current ?? []);
    } finally {
      if (loadController.current === controller) loadController.current = null;
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    void load("initial");
    return () => loadController.current?.abort();
  }, [load]);

  const disconnect = useCallback(async () => {
    if (disconnecting) return;
    loadController.current?.abort();
    setDisconnecting(true);
    setError(null);
    setErrorCode(null);
    setAccount(null);
    setCourses(null);
    try {
      await clearCourseSession();
      await load("initial");
    } finally {
      setDisconnecting(false);
    }
  }, [disconnecting, load]);

  return (
    <Screen
      scroll={false}
      title="Courses"
      subtitle={account ? `Signed in as ${account.displayName}` : "Structured learning with your class or study group"}
      action={(
        <View style={styles.headerActions}>
          {account ? (
            <Button compact variant="quiet" loading={disconnecting} onPress={() => void disconnect()}>
              Disconnect
            </Button>
          ) : null}
          <Button compact variant="secondary" onPress={() => setJoinOpen(true)}>Join</Button>
        </View>
      )}
    >
      {error ? (
        <View style={styles.errorBanner} accessibilityRole="alert">
          <Text style={styles.errorText}>{error}</Text>
          {errorCode === "notorganic_auth_adapter_unavailable" ? (
            <Button
              compact
              variant="quiet"
              onPress={() => void Linking.openURL(PRODUCT_LINKS.courses)}
            >
              Open Courses on web
            </Button>
          ) : (
            <Button compact variant="quiet" onPress={() => void load("refresh")}>Try again</Button>
          )}
        </View>
      ) : null}

      {courses === null ? (
        <View style={styles.loading}>
          <ActivityIndicator color={theme.colors.primaryText} />
          <Text style={styles.loadingText}>Loading your courses…</Text>
        </View>
      ) : (
        <FlatList
          data={courses}
          keyExtractor={(course) => course.id}
          contentContainerStyle={styles.list}
          refreshControl={(
            <RefreshControl
              refreshing={refreshing}
              onRefresh={() => void load("refresh")}
              tintColor={theme.colors.primaryText}
            />
          )}
          renderItem={({ item }) => (
            <CourseRow course={item} onPress={() => router.push(`/course/${item.id}`)} />
          )}
          ListEmptyComponent={(
            <EmptyState
              title="No courses yet"
              body="Join a course with the invite code your teacher or study group shared."
              action={<Button onPress={() => setJoinOpen(true)}>Join a course</Button>}
            />
          )}
        />
      )}

      <JoinCourseSheet
        visible={joinOpen}
        onClose={() => setJoinOpen(false)}
        onJoined={(courseId) => {
          setJoinOpen(false);
          void load("refresh");
          router.push(`/course/${courseId}`);
        }}
      />
    </Screen>
  );
}

function CourseRow({ course, onPress }: { course: CourseListItem; onPress: () => void }) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const progress = course.lessonCount > 0
    ? Math.round((course.completedLessons / course.lessonCount) * 100)
    : 0;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${course.title}. ${course.completedLessons} of ${course.lessonCount} lessons done.`}
      onPress={onPress}
      style={({ pressed }) => [styles.card, pressed && styles.cardPressed]}
    >
      <View style={styles.cardHeader}>
        <Text numberOfLines={2} style={styles.cardTitle}>{course.title}</Text>
        <Text style={styles.role}>{course.role.toUpperCase()}</Text>
      </View>
      {course.description ? (
        <Text numberOfLines={2} style={styles.cardBody}>{course.description}</Text>
      ) : null}
      <View style={styles.progressTrack}>
        <View style={[styles.progressFill, { width: `${progress}%` }]} />
      </View>
      <Text style={styles.meta}>
        {course.completedLessons} / {course.lessonCount} lessons · {course.memberCount}{" "}
        {course.memberCount === 1 ? "member" : "members"}
      </Text>
    </Pressable>
  );
}

function JoinCourseSheet({
  visible,
  onClose,
  onJoined,
}: {
  visible: boolean;
  onClose: () => void;
  onJoined: (courseId: string) => void;
}) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const [code, setCode] = useState("");
  const [acceptTeacherAccess, setAcceptTeacherAccess] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<string | null>(null);
  const joinController = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!visible) return;
    setCode("");
    setAcceptTeacherAccess(false);
    setError(null);
    setErrorCode(null);
  }, [visible]);

  useEffect(() => () => joinController.current?.abort(), []);

  const close = useCallback(() => {
    joinController.current?.abort();
    onClose();
  }, [onClose]);

  const submit = async () => {
    const trimmed = code.trim();
    if (!trimmed || busy) return;
    const controller = new AbortController();
    joinController.current?.abort();
    joinController.current = controller;
    setBusy(true);
    setError(null);
    setErrorCode(null);
    try {
      const snapshot = await joinCourse(trimmed, acceptTeacherAccess, { signal: controller.signal });
      if (controller.signal.aborted) return;
      onJoined(snapshot.course.id);
    } catch (caught) {
      if (controller.signal.aborted || (caught instanceof Error && caught.name === "AbortError")) return;
      const errorCode = caught instanceof CourseApiError ? caught.code : null;
      setErrorCode(errorCode);
      setError(errorCode === "notorganic_auth_adapter_unavailable"
        ? "Hosted course sign-in is unavailable on this server. Open Courses on the web to sign in or contact the server administrator."
        : caught instanceof CourseApiError
          ? caught.message
          : "Could not join this course. Check the code and try again.");
    } finally {
      if (joinController.current === controller) joinController.current = null;
      setBusy(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="slide" statusBarTranslucent onRequestClose={close}>
      <View style={styles.overlay}>
        <Pressable accessibilityRole="button" accessibilityLabel="Close join course" style={styles.scrim} onPress={close} />
        <View accessibilityViewIsModal accessibilityLabel="Join a course" style={styles.sheet}>
          <Text style={styles.sheetTitle}>Join a course</Text>
          <Text style={styles.sheetBody}>Paste the invite code your teacher or study group shared.</Text>
          <TextInput
            accessibilityLabel="Invite code"
            autoCapitalize="none"
            autoCorrect={false}
            autoFocus
            placeholder="Invite code"
            placeholderTextColor={theme.colors.textFaint}
            value={code}
            onChangeText={setCode}
            onSubmitEditing={() => void submit()}
            style={styles.input}
          />
          {/*
            Teacher access is the learner's own disclosure decision, so it is
            off until they turn it on — never implied by joining.
          */}
          <View style={styles.consentRow}>
            <View style={styles.consentCopy}>
              <Text style={styles.consentTitle}>Let teachers see my work</Text>
              <Text style={styles.consentBody}>
                Shares your submissions and progress with course teachers. You can join without this.
              </Text>
            </View>
            <Switch
              accessibilityLabel="Let teachers see my work"
              value={acceptTeacherAccess}
              onValueChange={setAcceptTeacherAccess}
              trackColor={{ false: theme.colors.border, true: theme.colors.primary }}
              thumbColor={acceptTeacherAccess ? theme.colors.primaryInk : theme.colors.textFaint}
            />
          </View>
          {error ? <Text accessibilityRole="alert" style={styles.errorText}>{error}</Text> : null}
          <View style={styles.sheetActions}>
            {errorCode === "notorganic_auth_adapter_unavailable" ? (
              <Button variant="secondary" onPress={() => void Linking.openURL(PRODUCT_LINKS.courses)}>
                Open Courses on web
              </Button>
            ) : (
              <Button loading={busy} disabled={!code.trim()} onPress={() => void submit()}>Join course</Button>
            )}
            <Button variant="quiet" onPress={close}>Cancel</Button>
          </View>
        </View>
      </View>
    </Modal>
  );
}

